#!/usr/bin/env node
/**
 * Import strapi/seed/strapi-content-bundle.json into the FRESH Strapi instance
 * via the REST Content API. Generated by scripts/generate-strapi-seed.ts.
 *
 * USAGE:
 *   node scripts/import-strapi-seed.mjs                 # full import (needs env)
 *   node scripts/import-strapi-seed.mjs --dry-run       # validate + print plan, no API calls
 *   node scripts/import-strapi-seed.mjs --self-check    # offline bundle validation only
 *   node scripts/import-strapi-seed.mjs --upload-covers # also download+upload cover images
 *   node scripts/import-strapi-seed.mjs --update        # PUT existing entries instead of skipping
 *
 * ENV (from .env):
 *   VITE_STRAPI_URL / STRAPI_URL             — Strapi base URL (e.g. http://localhost:1337)
 *   VITE_STRAPI_API_TOKEN / STRAPI_API_TOKEN — Strapi API token with write permissions
 *
 * SEMANTICS
 *   - Idempotent: entries are found by slug; existing ones are SKIPPED (Strapi
 *     is the source of truth after import — re-running never clobbers edits).
 *   - Draft & Publish types (posts, books, videos, pages) are created then
 *     published via POST /api/{uid}/{documentId}/publish.
 *   - Relations use documentIds; media attaches by numeric id.
 *   - Local sample PDFs (public/pdfs/*.pdf) are uploaded and attached to book
 *     pdf_file automatically. Cover images are only fetched with --upload-covers.
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const BUNDLE_PATH = path.resolve(__dirname, "..", "strapi", "seed", "strapi-content-bundle.json");

/* ─── Offline validation (pure, exported for tests) ───────────────── */

export const CONTENT_KEYS = ["categories", "tags", "navigation", "pages", "posts", "books", "videos"];

export function validateBundle(bundle) {
  const errors = [];
  if (!bundle || typeof bundle !== "object") {
    return ["bundle is not an object"];
  }
  for (const key of CONTENT_KEYS) {
    if (!Array.isArray(bundle[key])) errors.push(`${key} must be an array`);
  }
  if (!bundle.siteSettings || typeof bundle.siteSettings !== "object") {
    errors.push("siteSettings must be an object");
  }
  // Unique slugs per keyed type (navigation is keyed by url, so skip it)
  for (const key of ["categories", "posts", "books", "videos", "pages"]) {
    const slugs = (bundle[key] || []).map((x) => x?.slug).filter(Boolean);
    const dups = slugs.filter((s, i) => slugs.indexOf(s) !== i);
    if (dups.length > 0) errors.push(`${key}: duplicate slugs: ${[...new Set(dups)].join(", ")}`);
  }
  return errors;
}

export function bundleStats(bundle) {
  const counts = {};
  for (const key of CONTENT_KEYS) counts[key] = (bundle[key] || []).length;
  counts.siteSettings = bundle.siteSettings ? 1 : 0;
  return counts;
}

/* ─── REST helpers ────────────────────────────────────────────────── */

function loadEnv() {
  const envPath = path.resolve(__dirname, "..", ".env");
  if (!fs.existsSync(envPath)) return;
  for (const line of fs.readFileSync(envPath, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eqIdx = trimmed.indexOf("=");
    if (eqIdx === -1) continue;
    const key = trimmed.slice(0, eqIdx).trim();
    const val = trimmed.slice(eqIdx + 1).trim();
    if (!process.env[key]) process.env[key] = val;
  }
}

async function api(strapiUrl, token, endpoint, options = {}) {
  const url = `${strapiUrl}/api${endpoint}`;
  const res = await fetch(url, {
    method: options.method || "GET",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
      ...(options.headers || {}),
    },
    body: options.body ? JSON.stringify(options.body) : undefined,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Strapi ${options.method || "GET"} ${endpoint} failed: ${res.status} ${res.statusText} — ${text.slice(0, 200)}`);
  }
  if (res.status === 204) return null;
  return res.json();
}

/** Find one entry by slug across published + draft states (D&P types only). */
async function findBySlug(strapiUrl, token, uid, slug, withStatus = true) {
  const q = `filters[slug][$eq]=${encodeURIComponent(slug)}`;
  if (!withStatus) {
    const { data } = await api(strapiUrl, token, `/${uid}?${q}`);
    return data && data.length > 0 ? data[0] : null;
  }
  for (const status of ["published", "draft"]) {
    const { data } = await api(strapiUrl, token, `/${uid}?${q}&status=${status}`);
    if (data && data.length > 0) return data[0];
  }
  return null;
}

async function ensurePublished(strapiUrl, token, uid, entry) {
  if (entry?.publishedAt) return true;
  try {
    await api(strapiUrl, token, `/${uid}/${entry.documentId}/publish`, { method: "POST" });
    return true;
  } catch (err) {
    console.warn(`  ⚠ publish ${entry.documentId}: ${err.message}`);
    return false;
  }
}

/** Upload a local file buffer → returns the media object ({ id, url }). */
async function uploadFile(strapiUrl, token, buffer, filename, contentType) {
  const form = new FormData();
  form.append("files", new Blob([buffer], { type: contentType }), filename);
  const res = await fetch(`${strapiUrl}/api/upload`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}` },
    body: form,
  });
  if (!res.ok) throw new Error(`upload ${filename} failed: ${res.status} ${res.statusText}`);
  const data = await res.json();
  return data[0];
}

/* ─── Import orchestration ────────────────────────────────────────── */

const DRAFT_PUBLISH = new Set(["posts", "books", "videos", "pages"]);

/** Reference metadata is NOT a Strapi field — never send it to the API. */
const REFERENCE_KEYS = ["cover_image_url", "pdf_local_path", "thumbnail_url"];

function stripReferenceMetadata(entry) {
  for (const key of REFERENCE_KEYS) delete entry[key];
  return entry;
}

async function importSection(strapiUrl, token, uid, entries, options, stats) {
  for (const entry of entries) {
    stripReferenceMetadata(entry);
    const slug = entry.slug;
    const existing = await findBySlug(strapiUrl, token, uid, slug, DRAFT_PUBLISH.has(uid));
    if (existing) {
      if (!options.update) {
        console.log(`  = ${slug} (exists, skipped)`);
        stats.skipped += 1;
        continue;
      }
      await api(strapiUrl, token, `/${uid}/${existing.documentId}`, {
        method: "PUT",
        body: { data: entry },
      });
      if (DRAFT_PUBLISH.has(uid)) await ensurePublished(strapiUrl, token, uid, existing);
      console.log(`  ~ ${slug} (updated)`);
      stats.updated += 1;
      continue;
    }
    const { data } = await api(strapiUrl, token, `/${uid}`, { method: "POST", body: { data: entry } });
    if (DRAFT_PUBLISH.has(uid)) {
      const ok = await ensurePublished(strapiUrl, token, uid, data);
      console.log(`  + ${slug} (created${ok ? ", published" : ""})`);
    } else {
      console.log(`  + ${slug} (created)`);
    }
    stats.created += 1;
  }
}

async function importMedia(strapiUrl, token, books, options) {
  const publicDir = path.resolve(__dirname, "..", "public");
  let pdfs = 0;
  let covers = 0;
  for (const book of books) {
    // Local sample PDF → book.pdf_file
    if (book.pdf_local_path) {
      const filePath = path.join(publicDir, book.pdf_local_path.replace(/^\//, ""));
      if (fs.existsSync(filePath)) {
        try {
          const media = await uploadFile(
            strapiUrl,
            token,
            fs.readFileSync(filePath),
            path.basename(book.pdf_local_path),
            "application/pdf",
          );
          book.pdf_file = media.id;
          pdfs += 1;
        } catch (err) {
          console.warn(`  ⚠ pdf for ${book.slug}: ${err.message}`);
        }
      }
    }
    // Remote cover → book.cover_image (opt-in; requires network)
    if (options.uploadCovers && book.cover_image_url) {
      try {
        const res = await fetch(book.cover_image_url);
        if (res.ok) {
          const buffer = Buffer.from(await res.arrayBuffer());
          const media = await uploadFile(strapiUrl, token, buffer, `${book.slug}-cover.jpg`, "image/jpeg");
          book.cover_image = media.id;
          covers += 1;
        }
      } catch (err) {
        console.warn(`  ⚠ cover for ${book.slug}: ${err.message}`);
      }
    }
    // Reference metadata is not a Strapi field — drop it from the payload
    delete book.cover_image_url;
    delete book.pdf_local_path;
    delete book.thumbnail_url;
  }
  console.log(`  media: ${pdfs} PDF(s) uploaded, ${covers} cover(s) uploaded`);
}

async function importSiteSettings(strapiUrl, token, siteSettings) {
  const payload = { data: siteSettings };
  try {
    await api(strapiUrl, token, "/sitesetting", { method: "PUT", body: payload });
    console.log("  + Site Settings (upserted)");
  } catch (err) {
    console.warn(`  ⚠ Site Settings: ${err.message}`);
  }
}

async function main() {
  const argv = process.argv.slice(2);
  const options = {
    dryRun: argv.includes("--dry-run"),
    selfCheck: argv.includes("--self-check"),
    update: argv.includes("--update"),
    uploadCovers: argv.includes("--upload-covers"),
  };
  loadEnv();

  if (!fs.existsSync(BUNDLE_PATH)) {
    console.error(`Bundle not found at ${BUNDLE_PATH}. Run: npx tsx scripts/generate-strapi-seed.ts`);
    process.exit(1);
  }
  const bundle = JSON.parse(fs.readFileSync(BUNDLE_PATH, "utf8"));

  // Validation always runs
  const errors = validateBundle(bundle);
  if (errors.length > 0) {
    console.error("Bundle validation FAILED:");
    for (const e of errors) console.error(`  ✗ ${e}`);
    process.exit(1);
  }
  const statsObj = bundleStats(bundle);
  console.log("Bundle valid:", JSON.stringify(statsObj));

  if (options.selfCheck) {
    console.log("\nSelf-check passed — bundle is structurally valid.");
    return;
  }

  if (options.dryRun) {
    console.log("\nDry run — no API calls. Sections to import:");
    for (const key of CONTENT_KEYS) console.log(`  ${key}: ${bundle[key].length}`);
    console.log(`  siteSettings: 1`);
    return;
  }

  const strapiUrl = (process.env.VITE_STRAPI_URL || process.env.STRAPI_URL || "").replace(/\/$/, "");
  const token = process.env.VITE_STRAPI_API_TOKEN || process.env.STRAPI_API_TOKEN || "";
  if (!strapiUrl || !token) {
    console.error("Missing VITE_STRAPI_URL or VITE_STRAPI_API_TOKEN for the import phase.");
    process.exit(1);
  }

  const stats = { created: 0, updated: 0, skipped: 0 };

  // Relation maps: slug → documentId
  const catMap = {};
  const tagMap = {};
  for (const c of bundle.categories) {
    await importSection(strapiUrl, token, "categories", [c], options, stats);
    const found = await findBySlug(strapiUrl, token, "categories", c.slug, false);
    if (found) catMap[c.slug] = found.documentId;
  }
  for (const t of bundle.tags) {
    await importSection(strapiUrl, token, "tags", [t], options, stats);
    const found = await findBySlug(strapiUrl, token, "tags", t.slug, false);
    if (found) tagMap[t.slug] = found.documentId;
  }

  // Navigation has no slug — import by URL (flat header items)
  for (const n of bundle.navigation) {
    const q = `filters[url][$eq]=${encodeURIComponent(n.url)}`;
    const { data } = await api(strapiUrl, token, `/navigations?${q}`);
    if (data && data.length > 0) {
      if (options.update) {
        await api(strapiUrl, token, `/navigations/${data[0].documentId}`, { method: "PUT", body: { data: n } });
        console.log(`  ~ ${n.url} (updated)`);
        stats.updated += 1;
      } else {
        console.log(`  = ${n.url} (exists, skipped)`);
        stats.skipped += 1;
      }
    } else {
      await api(strapiUrl, token, "/navigations", { method: "POST", body: { data: n } });
      console.log(`  + ${n.url} (created)`);
      stats.created += 1;
    }
  }

  // Pages (D&P) — plain create
  await importSection(strapiUrl, token, "pages", bundle.pages, options, stats);

  // Posts — attach category/tag relations by documentId
  const posts = bundle.posts.map((p) => ({
    ...p,
    categories: (p.categories || []).map((s) => catMap[s]).filter(Boolean),
    tags: (p.tags || []).map((s) => tagMap[s]).filter(Boolean),
  }));
  await importSection(strapiUrl, token, "posts", posts, options, stats);

  // Books — relations + media
  const books = bundle.books.map((b) => ({
    ...b,
    categories: (b.categories || []).map((s) => catMap[s]).filter(Boolean),
    tags: (b.tags || []).map((s) => tagMap[s]).filter(Boolean),
  }));
  await importMedia(strapiUrl, token, books, options);
  await importSection(strapiUrl, token, "books", books, options, stats);

  await importSection(strapiUrl, token, "videos", bundle.videos, options, stats);
  await importSiteSettings(strapiUrl, token, bundle.siteSettings);

  console.log(
    `\nDone. created=${stats.created} updated=${stats.updated} skipped=${stats.skipped} (content).`,
  );
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  main().catch((err) => {
    console.error("Import failed:", err);
    process.exit(1);
  });
}
